867	func (e *Engine) Fill(t Trade) (FillResult, error) {
868		if t.TradeID <= 0 {
869			return FillResult{}, fmt.Errorf("成交编号必须为正: %d", t.TradeID)
870		}
871	
872		e.mu.Lock()
873		defer e.mu.Unlock()
874	
875		if prev, ok := e.fills[t.TradeID]; ok {
876			if prev.orderID != t.OrderID || prev.symbol != t.Symbol || prev.side != t.Side ||
877				prev.price != t.Price || prev.qty != t.Qty {
878				reason := fmt.Sprintf("成交编号 %d 已用于不同内容的成交: 原有 (订单=%d, 合约=%s, 方向=%s, 价格=%d, 数量=%d)",
879					t.TradeID, prev.orderID, prev.symbol, prev.side, prev.price, prev.qty)
880				e.appendRecord(Record{
881					Kind:       RecordRejected,
882					Symbol:     t.Symbol,
883					Side:       t.Side,
884					OrderID:    t.OrderID,
885					TradeID:    t.TradeID,
886					Qty:        t.Qty,
887					TradePrice: t.Price,
888					Reason:     reason,
889				}, e.symbols[t.Symbol])
890				return FillResult{}, fmt.Errorf("%s", reason)
891			}
892			return prev.result, nil // 幂等重放：返回原结果，不新增事件、不再次记账
893		}
894	
895		reason := e.validateFill(t)
896		if reason != "" {
897			st := e.symbols[t.Symbol]
898			e.appendRecord(Record{
899				Kind:       RecordRejected,
900				Symbol:     t.Symbol,
901				Side:       t.Side,
902				OrderID:    t.OrderID,
903				TradeID:    t.TradeID,
904				Qty:        t.Qty,
905				TradePrice: t.Price,
906				Reason:     reason,
907			}, st)
908			return FillResult{}, fmt.Errorf("成交 %d 被拒绝: %s", t.TradeID, reason)
909		}
910	
911		o := e.orders[t.OrderID]
912		st := e.symbols[o.Symbol]
913		amount, _ := mulPositive(t.Price, t.Qty) // validateFill 已校验单笔成交金额可乘，此处必然安全
914	
915		// 卖出成交的现金结算必须始终可表示：卖出所得加回现金余额后超出 int64 范围时
916		// 整笔拒绝，不依赖日内亏损保护是否开启，也不以设置账户总持仓金额上限为前提。
917		// 除一条拒绝记录外不改变任何业务状态（成交编号不被占用，持仓与卖单占用保留）。
918		if o.Side == Sell {
919			if _, ok := addInt64(e.cash, amount); !ok {
920				e.appendRecord(Record{
921					Kind:       RecordRejected,
922					Symbol:     o.Symbol,
923					Side:       o.Side,
924					OrderID:    o.ID,
925					TradeID:    t.TradeID,
926					Qty:        t.Qty,
927					TradePrice: t.Price,
928					Reason: fmt.Sprintf("卖出所得 %d 加入现金余额 %d 后超出 int64 范围，整笔拒绝",
929						amount, e.cash),
930				}, st)
931				return FillResult{}, fmt.Errorf("成交 %d: %w", t.TradeID, ErrInt64Overflow)
932			}
933		}
934	
935		// 启用风险保护时：先在假设成交后的状态上试算净值。越界则整笔拒绝，
936		// 除拒绝记录外不改变任何业务状态（成交编号也不被占用）。
937		if e.riskOpen {
938			var hypoCash, hypoPos int64
939			arithOK := true
940			if o.Side == Buy {
941				hypoCash, arithOK = subInt64(e.cash, amount) // 成交金额不超过买单占用，余额不会为负
942				if arithOK {
943					hypoPos, arithOK = addInt64(st.position, t.Qty)
944				}
945			} else {
946				hypoCash, arithOK = addInt64(e.cash, amount) // 上方已预检，此处必然安全
947				if arithOK {
948					hypoPos, arithOK = subInt64(st.position, t.Qty) // 可卖校验保证持仓足量
949				}
950			}
951			if arithOK {
952				if _, _, ok := e.valuationHypoLocked(hypoCash, o.Symbol, hypoPos, true, Quote{}, false); !ok {
953					arithOK = false
954				}
955			}
956			if !arithOK {
957				e.appendRecord(Record{
958					Kind:       RecordRejected,
959					Symbol:     o.Symbol,
960					Side:       o.Side,
961					OrderID:    o.ID,
962					TradeID:    t.TradeID,
963					Qty:        t.Qty,
964					TradePrice: t.Price,
965					Reason:     fmt.Sprintf("成交 %d 入账将使净值或亏损超出 int64 范围，整笔拒绝", t.TradeID),
966				}, st)
967				return FillResult{}, fmt.Errorf("成交 %d: %w", t.TradeID, ErrInt64Overflow)
968			}
969		}
970	
971		if o.Side == Buy {
972			// 释放限价占用，按实际成交金额扣现金；价差立即释放。
973			e.reservedCash -= o.Limit * t.Qty
974			e.cash -= amount
975			st.position += t.Qty
976			st.reservedBuy -= t.Qty
977		} else {
978			e.cash += amount
979			st.position -= t.Qty
980			st.reservedSell -= t.Qty
981		}
982		o.Filled += t.Qty
983		if o.Filled == o.Qty {
984			o.Status = StatusFilled
985		} else {
986			o.Status = StatusPartial
987		}
988	
989		res := FillResult{
990			TradeID:   t.TradeID,
991			OrderID:   o.ID,
992			Price:     t.Price,
993			Qty:       t.Qty,
994			Filled:    o.Filled,
995			Remaining: o.Remaining(),
996			Status:    o.Status,
